#!/usr/bin/env bash
V2=/home/usman/Bonsai-demo/dflash-training/v2; MD=/home/usman/Bonsai-demo/models/bonsai2-dspark; ROOT=/home/usman/Bonsai-demo; TAG=lrprobe
echo "[$(date +%H:%M:%S)] LR PROBE: continue from step600, lr 2e-4, 200 steps, anchors 256 (spark2)"
ssh spark2 "cd $ROOT && sudo docker run --rm --gpus all -v /home/usman:/home/usman bonsai/dflash-trainer:latest python3 -u $V2/train_dspark_v2.py --feats-dir $V2/feats --teacher-dir $V2/teacher --warm-start $MD/bonsai2_dspark_full2_step600.safetensors --out $MD/bonsai2_dspark_${TAG}.safetensors --epochs 1 --batch-size 2 --lr 2e-4 --num-anchors 256 --chunk-blocks 64 --log-every 10 --max-steps 200" 2>&1 | grep -E '^ep |max_steps|\[save\]|Traceback|Error|indexed|warm-start' | tail -30
ssh spark2 "sudo chown usman:p-usman $MD/bonsai2_dspark_${TAG}*.safetensors; ls -la $MD/bonsai2_dspark_${TAG}.safetensors" | awk '{print "ckpt:",$5,$9}'
echo "[$(date +%H:%M:%S)] convert + quantize on spark2"
ssh spark2 "cd $ROOT && python3 -c \"import sys; sys.path.insert(0,'$ROOT/dflash-training'); from convert_safetensors_to_dspark import convert_to_dspark; convert_to_dspark('$MD/bonsai2_dspark_${TAG}.safetensors','$MD/bonsai2-dspark-${TAG}-dspark-raw.gguf')\" >/dev/null 2>&1; python3 $ROOT/llama.cpp/gguf-py/gguf/scripts/gguf_dspark_to_dflash.py $MD/bonsai2-dspark-${TAG}-dspark-raw.gguf $ROOT/models/bonsai2-gguf/27B/Ternary-Bonsai-2-27B-PQ2_0.gguf $MD/bonsai2-dspark-${TAG}-conv.gguf --drop-shared-tensors >/dev/null 2>&1; LD_LIBRARY_PATH=$ROOT/bin/cuda $ROOT/bin/cuda/llama-quantize $MD/bonsai2-dspark-${TAG}-conv.gguf $MD/bonsai2-dspark-${TAG}-Q4_K_M.gguf Q4_K_M >/dev/null 2>&1; rm -f $MD/bonsai2-dspark-${TAG}-dspark-raw.gguf $MD/bonsai2-dspark-${TAG}-conv.gguf; ls -la $MD/bonsai2-dspark-${TAG}-Q4_K_M.gguf" | awk '{print "gguf:",$5,$9}'
echo "[$(date +%H:%M:%S)] eval K=5 exact (200-tok x3 + long-form x6) on spark2"
sed "s#bonsai2-dspark-full1ep1-Q4_K_M.gguf#bonsai2-dspark-${TAG}-Q4_K_M.gguf#g; s#RESULT full1ep1#RESULT ${TAG}#g; s#for K in 4 5; do for W in math code code2#for K in 5; do for W in math code code2#; s#for K in 5 7; do for TAU in 0.02 0.05#for K in 5; do for TAU in 0.05#" /tmp/ep1_sweep.sh > /tmp/${TAG}_sweep.sh
scp -q /tmp/${TAG}_sweep.sh spark2:/tmp/${TAG}_sweep.sh && ssh spark2 "bash /tmp/${TAG}_sweep.sh" | grep -E '^RESULT|DONE'
echo "[$(date +%H:%M:%S)] LR PROBE FINISHED"
